code.text:
.grid { display: grid; gap: 16px; }

@media (width >= 700px) { .grid { grid-template-columns: 1fr 1fr; } }
@media (width >= 1100px) { .grid { grid-template-columns: repeat(3, 1fr); } }

items.passage:
