code.text:
.article { width: min(100% - 32px, 70ch); margin-inline: auto; }
h1 { font-size: clamp(1.75rem, 1.2rem + 2vw, 3rem); }
.screen { min-height: 100dvh; }
img { max-width: 100%; height: auto; }

.button {
  transition: background-color 150ms ease, transform 150ms ease-out 50ms;
  /*          xossa             davomiylik  egri chiziq  kechikish */
}
.button:hover { transform: translateY(-2px) scale(1.02); }

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.4; }
}
.skeleton { animation: pulse 1.5s ease-in-out infinite; }

@media (prefers-reduced-motion: reduce) {
  .hero { animation: none; }
}

